const PALETTE = [
  "#FF0077",
  "#00FFDD",
  "#AA00FF",
  "#FFFF00",
  "#FFFFFF",
  "#222222"
];

const PADDLE_RADIUS = 120;
const PADDLE_WIDTH = 50;
const BLOCK_SIZE = 30;
const OVERFLOW_MAX = 100;
const MAX_PADDLE_SEGMENTS = 4;

// Helper to get a color from palette, or a random one
function getPaletteColor(index) {
  if (index === undefined) return GF.math.pick(PALETTE.slice(0, PALETTE.length - 2)); // Avoid white/black for blocks
  return PALETTE[index % PALETTE.length];
}

class Block {
  constructor(x, y, colorIndex, type = 'normal') {
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.colorIndex = colorIndex;
    this.color = getPaletteColor(colorIndex);
    this.type = type; // 'normal', 'wildcard', 'bomb'
    this.size = BLOCK_SIZE;
    this.active = true;
  }

  draw(ctx) {
    if (!this.active) return;
    ctx.fillStyle = this.color;
    if (this.type === 'wildcard') {
      ctx.strokeStyle = PALETTE[4]; // White outline
      ctx.lineWidth = 3;
      GF.Draw.roundRect(ctx, this.x - this.size / 2, this.y - this.size / 2, this.size, this.size, 5, this.color);
      ctx.strokeRect(this.x - this.size / 2, this.y - this.size / 2, this.size, this.size);
    } else if (this.type === 'bomb') {
      ctx.fillStyle = PALETTE[5]; // Black bomb
      ctx.strokeStyle = PALETTE[0]; // Red outline
      ctx.lineWidth = 3;
      GF.Draw.roundRect(ctx, this.x - this.size / 2, this.y - this.size / 2, this.size, this.size, 5, PALETTE[5]);
      ctx.strokeRect(this.x - this.size / 2, this.y - this.size / 2, this.size, this.size);
      GF.Draw.text(ctx, '💣', this.x, this.y, { size: this.size * 0.7, color: PALETTE[4] });
    } else {
      GF.Draw.roundRect(ctx, this.x - this.size / 2, this.y - this.size / 2, this.size, this.size, 5, this.color);
    }
  }
}

const game = new GF.Game({
  id: 'color-cascade',
  title: 'Color Cascade',
  width: 960,
  height: 540,
  palette: PALETTE,
  background: PALETTE[5]
});

let paddle = {
  x: game.W / 2,
  y: game.H - PADDLE_RADIUS / 2,
  rotation: 0, // radians
  segments: [],
  numSegments: 3
};

let blocks = [];
let overflow = 0;
let combo = 0;
let lastCatchTime = 0;
let nextBlockTime = 0;
let fallSpeed = 70; // pixels/sec
let blockSpawnInterval = 1.5; // seconds
let paddleRotationSpeed = 3;

function resetGameVariables() {
  paddle.rotation = 0;
  paddle.numSegments = 3;
  paddle.segments = [];
  blocks = [];
  overflow = 0;
  combo = 0;
  lastCatchTime = 0;
  nextBlockTime = 0;
  fallSpeed = 70;
  blockSpawnInterval = 1.5;
  createPaddleSegments();
}

function createPaddleSegments() {
  paddle.segments = [];
  let availableColors = [0, 1, 2, 3]; // Indices for palette, excluding white/black
  for (let i = 0; i < paddle.numSegments; i++) {
    const colorIndex = GF.math.pick(availableColors);
    availableColors = availableColors.filter(c => c !== colorIndex);
    if (availableColors.length === 0) availableColors = [0, 1, 2, 3]; // replenish if needed
    paddle.segments.push({ colorIndex, color: getPaletteColor(colorIndex) });
  }
}

function spawnBlock() {
  const x = GF.math.rand(BLOCK_SIZE, game.W - BLOCK_SIZE);
  const y = -BLOCK_SIZE;
  let colorIndex = GF.math.pick(paddle.segments).colorIndex;
  let type = 'normal';

  // Difficulty progression for special blocks
  if (game.time > 20 && game.rng() < 0.1) {
    type = GF.math.pick(['wildcard', 'bomb']);
    GF.Sfx.beep({ freq: 800, dur: 0.05, type: 'sine', vol: 0.2 });
  }

  blocks.push(new Block(x, y, colorIndex, type));
}

game.add('play', {
  init() {
    resetGameVariables();
  },
  reset() {
    resetGameVariables();
  },
  update(dt) {
    // Difficulty ramp
    fallSpeed = 70 + game.time * 2;
    blockSpawnInterval = Math.max(0.5, 1.5 - game.time * 0.01);
    paddle.numSegments = Math.min(MAX_PADDLE_SEGMENTS, 3 + Math.floor(game.time / 30));
    if (paddle.segments.length !== paddle.numSegments) createPaddleSegments();

    // Rotate paddle
    if (game.input.keys['ArrowLeft'] || game.input.keys['KeyA']) {
      paddle.rotation -= paddleRotationSpeed * dt;
      GF.Sfx.beep({ freq: 200, dur: 0.01, type: 'sine', vol: 0.02, delay: 0 });
    }
    if (game.input.keys['ArrowRight'] || game.input.keys['KeyD']) {
      paddle.rotation += paddleRotationSpeed * dt;
      GF.Sfx.beep({ freq: 200, to: 210, dur: 0.01, type: 'sine', vol: 0.02, delay: 0 });
    }
    paddle.rotation %= GF.math.TAU;

    // Spawn blocks
    nextBlockTime -= dt;
    if (nextBlockTime <= 0) {
      spawnBlock();
      nextBlockTime = blockSpawnInterval;
    }

    // Update blocks
    for (let i = blocks.length - 1; i >= 0; i--) {
      const block = blocks[i];
      if (!block.active) continue;

      block.y += fallSpeed * dt;

      // Check for collision with paddle
      const dx = block.x - paddle.x;
      const dy = block.y - paddle.y;
      const distToPaddleCenter = GF.math.dist(block.x, block.y, paddle.x, paddle.y);

      if (distToPaddleCenter < PADDLE_RADIUS + BLOCK_SIZE / 2) {
        // Check if block is below the paddle's top edge (to prevent catching blocks from above)
        if (block.y > paddle.y - PADDLE_WIDTH / 2) {
          const angle = (Math.atan2(dy, dx) - paddle.rotation + GF.math.TAU) % GF.math.TAU;
          const segmentAngle = GF.math.TAU / paddle.numSegments;
          const segmentIndex = Math.floor(angle / segmentAngle);

          if (segmentIndex >= 0 && segmentIndex < paddle.numSegments) {
            const targetSegment = paddle.segments[segmentIndex];

            let matched = false;
            if (block.type === 'wildcard') {
              game.addScore(10);
              matched = true;
              game.burst(block.x, block.y, { count: 15, speed: 150, size: 8, life: 0.8, colors: [PALETTE[4], targetSegment.color], spread: GF.math.TAU });
              GF.Sfx.beep({ freq: 900, to: 1200, dur: 0.1, type: 'triangle', vol: 0.3 });
              game.flash(PALETTE[4], 0.3);
            } else if (block.type === 'bomb') {
              game.addScore(25);
              matched = true;
              game.burst(block.x, block.y, { count: 30, speed: 200, size: 10, life: 1, colors: [PALETTE[0], PALETTE[3], PALETTE[4]], spread: GF.math.TAU });
              game.shake(10, 0.4);
              game.hitStop(0.15);
              GF.Sfx.noise({ dur: 0.2, vol: 0.5, freq: 200 });
              GF.Sfx.beep({ freq: 100, to: 50, dur: 0.3, type: 'sawtooth', vol: 0.4 });
              // Clear nearby blocks
              for (const otherBlock of blocks) {
                if (otherBlock.active && GF.math.dist(block.x, block.y, otherBlock.x, otherBlock.y) < BLOCK_SIZE * 3) {
                  otherBlock.active = false;
                  game.burst(otherBlock.x, otherBlock.y, { count: 8, speed: 100, size: 5, life: 0.5, colors: [otherBlock.color] });
                }
              }
            } else if (targetSegment.colorIndex === block.colorIndex) {
              matched = true;
              game.addScore(10 + combo * 2);
              game.burst(block.x, block.y, { count: 10, speed: 100, size: 6, life: 0.5, colors: [block.color] });
              game.flash(block.color, 0.2);
              GF.Sfx.beep({ freq: 660, to: 880, dur: 0.08, type: 'sine', vol: 0.2 });

              const now = game.time;
              if (now - lastCatchTime < 0.5) {
                combo++;
                if (combo > 1) {
                  game.hitStop(0.05);
                  GF.Sfx.beep({ freq: 1000 + combo * 50, dur: 0.05, type: 'triangle', vol: 0.3 });
                }
              } else {
                combo = 1;
              }
              lastCatchTime = now;
            }

            if (matched) {
              block.active = false;
            } else {
              // Mismatch
              overflow += 10;
              game.burst(block.x, block.y, { count: 10, speed: 80, size: 5, life: 0.5, colors: [PALETTE[5]], spread: GF.math.TAU }); // Dark splatter
              GF.Sfx.noise({ dur: 0.1, vol: 0.3, freq: 500 });
              game.flash(PALETTE[0], 0.4); // Red flash
              block.active = false;
              combo = 0; // Break combo on mismatch
              if (overflow >= OVERFLOW_MAX * 0.7) game.shake(3, 0.1);
            }
          }
        }
      }

      // Check for missed blocks (off screen bottom)
      if (block.y > game.H + BLOCK_SIZE / 2) {
        if (block.active) {
          overflow += 15;
          game.burst(block.x, block.y, { count: 10, speed: 80, size: 5, life: 0.5, colors: [PALETTE[5]], spread: GF.math.TAU }); // Dark splatter
          GF.Sfx.noise({ dur: 0.1, vol: 0.3, freq: 500 });
          game.flash(PALETTE[0], 0.4); // Red flash
          combo = 0; // Break combo on miss
          if (overflow >= OVERFLOW_MAX * 0.7) game.shake(3, 0.1);
        }
        block.active = false;
      }
    }

    blocks = blocks.filter(b => b.active);

    // Check for game over
    if (overflow >= OVERFLOW_MAX) {
      game.gameOver({ message: 'OVERFLOW!' });
      GF.Sfx.melody([[392, 0.12], [330, 0.12], [262, 0.2]], { type: 'sawtooth', vol: 0.5 });
      game.shake(15, 0.6);
    }
  },
  draw(ctx) {
    // Background gradient
    const gradient = ctx.createLinearGradient(0, 0, game.W, game.H);
    gradient.addColorStop(0, PALETTE[5]);
    gradient.addColorStop(1, '#1A1A2E');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, game.W, game.H);

    // Draw paddle
    ctx.save();
    ctx.translate(paddle.x, paddle.y);
    ctx.rotate(paddle.rotation);
    const segmentAngle = GF.math.TAU / paddle.numSegments;
    for (let i = 0; i < paddle.numSegments; i++) {
      const segment = paddle.segments[i];
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, PADDLE_RADIUS + PADDLE_WIDTH / 2, i * segmentAngle - GF.math.TAU / 4, (i + 1) * segmentAngle - GF.math.TAU / 4);
      ctx.lineTo(0, 0);
      ctx.fillStyle = segment.color;
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.arc(0, 0, PADDLE_RADIUS - PADDLE_WIDTH / 2, i * segmentAngle - GF.math.TAU / 4, (i + 1) * segmentAngle - GF.math.TAU / 4);
      ctx.lineTo(0, 0);
      ctx.fillStyle = PALETTE[5]; // Inner part of paddle
      ctx.fill();
    }
    ctx.restore();

    // Draw blocks
    for (const block of blocks) {
      block.draw(ctx);
    }

    // Draw combo meter
    if (combo > 0) {
      GF.Draw.text(ctx, `COMBO x${combo}`, game.W / 2, game.H / 2 - 100, {
        size: 30 + combo * 2, // Larger for bigger combos
        color: PALETTE[3],
        weight: 'bold'
      });
    }

    // Draw overflow meter
    const overflowHeight = (overflow / OVERFLOW_MAX) * (game.H * 0.8);
    GF.Draw.roundRect(ctx, game.W - 30, game.H * 0.1, 20, game.H * 0.8, 10, PALETTE[2] + '33'); // Background
    GF.Draw.roundRect(ctx, game.W - 30, game.H * 0.9 - overflowHeight, 20, overflowHeight, 10, PALETTE[0]); // Fill

    // Vignette
    GF.Draw.vignette(ctx, game.W, game.H, 0.4);
  }
});

game.titleScreen({ subtitle: 'Rotate paddle with A/D or Left/Right arrows' });
